#include "CaptureStrategy.h"
#include "../AreaSelector.h"
#include "../CaptureGeometry.h"
#include "../OverlayAnnotations.h"

#include <QClipboard>
#include <QDebug>
#include <QFileDialog>
#include <QGuiApplication>
#include <QStandardPaths>

namespace Capture {

// This file provides the implementation for the CaptureStrategy base class
// The signals are automatically generated by Qt's MOC system

QPixmap CaptureStrategy::cropWithAnnotations(const QPixmap &shot, const QRect &virtualGeometry,
                                             const QRect &area,
                                             const QSharedPointer<OverlayAnnotations> &annotations)
{
    if (annotations && annotations->hasItems())
        return annotations->flattenedCrop(area);
    return cropVirtualArea(shot, virtualGeometry, area);
}

QSharedPointer<OverlayAnnotations> CaptureStrategy::attachAnnotations(
    const QList<AreaSelector*> &selectors, const QPixmap &frame, const QRect &virtualGeometry)
{
    if (!quickActionsEnabled())
        return {};
    // deleteLater: the last reference can drop inside one of the session's own signals.
    QSharedPointer<OverlayAnnotations> session(new OverlayAnnotations(frame, virtualGeometry),
                                               &QObject::deleteLater);
    for (AreaSelector *selector : selectors)
        selector->setAnnotations(session);
    return session;
}

void CaptureStrategy::copyAreaToClipboard(const QPixmap &shot, const QRect &virtualGeometry,
                                          const QRect &area,
                                          const QSharedPointer<OverlayAnnotations> &annotations)
{
    const QPixmap cropped = cropWithAnnotations(shot, virtualGeometry, area, annotations);
    if (cropped.isNull())
        return;

    QGuiApplication::clipboard()->setPixmap(cropped);
    qDebug() << "Selection copied to clipboard:" << cropped.size();
}

void CaptureStrategy::saveAreaToFile(const QPixmap &shot, const QRect &virtualGeometry,
                                     const QRect &area,
                                     const QSharedPointer<OverlayAnnotations> &annotations)
{
    const QPixmap cropped = cropWithAnnotations(shot, virtualGeometry, area, annotations);
    if (cropped.isNull())
        return;

    // The overlay is already torn down, so this dialog isn't hidden behind it.
    const QString fileName = QFileDialog::getSaveFileName(
        nullptr, "Save Screenshot",
        QStandardPaths::writableLocation(QStandardPaths::PicturesLocation) + "/screenshot.png",
        "Image Files (*.png *.jpg *.bmp)");
    if (!fileName.isEmpty())
        cropped.save(fileName);
}

} // namespace Capture
